contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient is zero");
        require(recipient != address(c), "recipient is contract");
        require(recipient != address(this), "recipient is test contract");

        uint contractBefore = address(c).balance;
        uint recipientBefore = recipient.balance;

        bool firstReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint contractAfterFirst = address(c).balance;
        uint recipientAfterFirst = recipient.balance;

        bool secondReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(
            (firstReverted && contractAfterFirst == contractBefore && recipientAfterFirst == recipientBefore && secondReverted) ||
            (!firstReverted && contractAfterFirst == contractBefore - 100 && recipientAfterFirst == recipientBefore + 100 && secondReverted && address(c).balance == contractAfterFirst && recipient.balance == recipientAfterFirst)
        );
    }

    receive() external payable {}
}

